/**
 * СГЕНЕРИРОВАНО scripts/sync-tradeable-data.ts из исходников sunflower-land — не править руками.
 * Что разрешено торговать на маркетплейсе по коду игры:
 *  - TRADE_RESOURCE_LIMITS — ресурсы (TRADE_LIMITS), имя → лимит листинга;
 *  - TRADEABLE_COLLECTIBLES / TRADEABLE_WEARABLES — предметы с датой открытия торговли (tradeAt);
 *  - PET_NFT_TRADE_WINDOWS — окна торговли питомцев по id, tradeAt null = только после конфига.
 * Обновление: npm run sfl:sync-tradeable (после npm run sfl:clone).
 */

export interface TradeRelease {
  name: string;
  /** ISO-дата, с которой предмет открыт для торговли. */
  tradeAt: string;
}

export interface PetTradeWindow {
  startId: number;
  endId: number;
  /** ISO-дата открытия торговли; null — конфиг не задал (не торгуется). */
  tradeAt: string | null;
}

